      for (let index = 0; index < chunk.length; index++) {
        const char = chunk[index];
        if (atStart) {
          atStart = false;
          if (char === '\uFEFF') continue;
        }

        const pairedLF = char === '\n' && previousCR;
        if (char === '\r' || (char === '\n' && !previousCR)) line++;
