'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const cases = [
  ['', []], ['\uFEFF', []], ['\n', [['']]], ['\r\n\r\n', [[''], ['']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
  [',,', [['', '', '']]], ['""', [['']]], ['""""', [['"']]],
  ['a"b, "c",d', [['a"b', ' "c"', 'd']]],
  ['\uFEFF"a,b","say ""hi"""\r\n"x\r\ny\rz\nw",tail,', [['a,b', 'say "hi"'], ['x\r\ny\rz\nw', 'tail', '']]],
  ['\uFEFF\uFEFF,x\uFEFF', [['\uFEFF', 'x\uFEFF']]],
  ['"😀",😀\n', [['😀', '😀']]],
  ['a;"b;c";\r\n', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\uD800b', [['a', 'b']], { delimiter: '\uD800' }],
  ['a\0"b\0c"', [['a', 'b\0c']], { delimiter: '\0' }],
];

test('grammar across every pair of chunk boundaries and code-unit chunks', () => {
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, options), expected);
    for (let first = 0; first <= text.length; first++) {
      for (let second = first; second <= text.length; second++) {
        const parser = createParser(options);
        const records = [
          ...parser.push(''), ...parser.push(text.slice(0, first)),
          ...parser.push(''), ...parser.push(text.slice(first, second)),
          ...parser.push(text.slice(second)), ...parser.end(),
        ];
        assert.deepEqual(records, expected, JSON.stringify({ text, first, second }));
        assert.deepEqual(parser.end(), []);
      }
    }
    const parser = createParser(options);
    const records = [];
    for (let i = 0; i < text.length; i++) records.push(...parser.push(text[i]));
    records.push(...parser.end());
    assert.deepEqual(records, expected);
  }
});

test('records emit at CR or LF without replay, including empty rows', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.push('a\r'), [['a']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\n"b\r'), []);
  assert.deepEqual(parser.push('\nc"\r'), [['b\r\nc']]);
  assert.deepEqual(parser.push('\n\nlast,'), [['']]);
  assert.deepEqual(parser.end(), [['last', '']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
  assert.throws(() => parser.push('new'), Error);
  const other = createParser();
  assert.deepEqual(other.push('separate\n'), [['separate']]);
});

test('validation and lifecycle', () => {
  for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, false, 1, {}, []]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const parser = createParser();
  for (const chunk of [undefined, null, false, 1, {}, [], new String('x')]) {
    assert.throws(() => parser.push(chunk), TypeError);
  }
  assert.deepEqual(parser.push('valid\n'), [['valid']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parse(1), TypeError);
});

test('syntax errors carry physical line numbers across all splits', () => {
  const invalid = [
    ['"a" ', 1], ['"a"x', 1], ['a\r\n"b"x', 2],
    ['"a\r\nb\rc\nd"x', 4], ['\r\n\r"a"\t', 3],
  ];
  const unfinished = [
    ['"', 1], ['"a\r', 2], ['"a\r\n', 2], ['\r\n"a\nb\r\nc\r', 5],
  ];
  for (const [items, atEnd] of [[invalid, false], [unfinished, true]]) {
    for (const [text, line] of items) {
      for (let split = 0; split <= text.length; split++) {
        const parser = createParser();
        assert.throws(() => {
          parser.push(text.slice(0, split));
          parser.push('');
          parser.push(text.slice(split));
          if (atEnd) parser.end();
        }, error => error instanceof SyntaxError && new RegExp(`\\bline ${line}\\b`).test(error.message));
      }
    }
  }
});

test('header conversion preserves duplicate names, special keys and padding', () => {
  const options = Object.freeze({ header: true });
  const objects = parse('x,x,x_2,x,__proto__,constructor,toString\na,b,c,d,p,q,r\nshort\n', options);
  assert.deepEqual(Object.keys(objects[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString']);
  assert.deepEqual(Object.values(objects[0]), ['a', 'b', 'c', 'd', 'p', 'q', 'r']);
  assert.deepEqual(Object.values(objects[1]), ['short', '', '', '', '', '', '']);
  assert.equal(Object.getPrototypeOf(objects[0]), Object.prototype);
  for (const key of Object.keys(objects[0])) {
    const descriptor = Object.getOwnPropertyDescriptor(objects[0], key);
    assert.equal(descriptor.enumerable, true);
    assert.equal(descriptor.writable, true);
  }
  assert.deepEqual(parse('', options), []);
  assert.deepEqual(parse('header\n', options), []);
  const records = Object.freeze([Object.freeze(['a']), Object.freeze(['one', 'ignored'])]);
  assert.deepEqual(toObjects(records, options), [{ a: 'one' }]);
  assert.deepEqual(records, [['a'], ['one', 'ignored']]);
  const header = Object.freeze(['x', 'x']);
  assert.deepEqual(toObjects(records, Object.freeze({ header })), [{ x: 'a', x_2: '' }, { x: 'one', x_2: 'ignored' }]);
});

